def main():
    rows=json.loads((HERE/'benchmark-observations-summary.json').read_text(encoding='utf-8'))
    studies=[]
    for row in rows:
        studies.append(f'<details class="research-row"><summary>{row["id"]:03d} · {escape(row["name"])}<small>{escape(" + ".join(row["review_scope"]))}</small></summary><p><strong>Strength:</strong> {escape(row["strength"])}</p><p><strong>Watch-out / transfer limit:</strong> {escape(row["watchout"])}</p><p><strong>Matrix application:</strong> {escape(row["application"])}</p><p>{escape(row["cohort"])} · <a href="{escape(row["source_url"],quote=True)}" target="_blank" rel="noopener noreferrer">Primary reference ↗</a> · Commercial outcome unverified.</p></details>')
    shots=[]
    for name,caption in [('navigator','Learn / Measure / Explore — useful, keyboard-operable navigation'),('collection','The Core Four — a coherent official-product collection'),('universe','Product discovery — filters, inspection and source boundaries'),('library','Library — search and filters before secondary navigation'),('products','Catalog — clear hierarchy and an accessible entry point'),('evidence','Evidence — inspect sources and their limitations'),('product-record','Product record — clear facts and disclosed manufacturer links'),('home-tablet','Tablet — separated copy, artwork and disclosure'),('home-mobile','Phone — full supporting copy and earlier product visibility'),('home-mobile375','375px — the same core experience in a smaller viewport')]:
        shots.append(f'<figure><a href="screenshots/{name}.jpg"><img class="screen" loading="lazy" src="screenshots/{name}.jpg" alt="{escape(caption)}"></a><figcaption>{escape(caption)} · click for the full capture</figcaption></figure>')
    (HERE/'index.html').write_text(PAGE.replace('__SHOTS__',''.join(shots)).replace('__BENCHMARKS__',''.join(studies)),encoding='utf-8',newline='\n')
    print('Review gallery generated with 100 original assessments and 13 browser screenshots.')

if __name__=='__main__':main()
